// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, address recipient) public {
        vm.assume(caller != address(0) && recipient != address(0) && caller != address(this) && recipient != address(this));
        vm.deal(address(c), 1 ether);
        uint256 initialBalance = address(c).balance;
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", recipient));
        if (!success) {
            assertTrue(caller != c.owner());
        } else {
            assertTrue(caller == c.owner());
            assertTrue(initialBalance == 0 || address(recipient).balance > 0 || address(c).balance == 0);
        }
    }
}

