pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(this));
        // Fund the contract
        vm.deal(address(c), 1 ether);
        // If caller is the owner (this), withdrawAll should empty the contract
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll(address)", address(this)));
        if (caller == address(this)) {
            // Owner call should succeed and transfer all balance
            assertTrue(success && address(c).balance == 0);
        } else {
            // Non-owner call should revert
            assertTrue(!success);
        }
    }
}

