pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        uint256 initialBalance = 1 ether;
        vm.deal(address(c), initialBalance);
        vm.prank(caller);
        c.withdrawAll(address(0xdead));
        uint256 finalBalance = address(c).balance;
        // The reference: if caller is owner, balance becomes 0; otherwise balance stays same
        bool rule = (caller == address(this)) ? (finalBalance == 0) : (finalBalance == initialBalance);
        assertTrue(rule);
    }
}

