contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        vm.deal(address(c), 1 ether);
        // Try to call withdrawAll as the owner (address(this))
        c.withdrawAll(recipient);
        // The owner is address(this); after the call, the contract balance should be 0
        // because the owner can withdraw all funds. For the buggy version, the owner
        // is blocked (require(msg.sender != owner)), so the balance remains unchanged.
        assertTrue(address(c).balance == 0 ether);
    }
}

