pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller) public {
        // Precondition: caller is not the owner
        vm.assume(caller != c.owner());

        uint256 balanceBefore = address(c).balance;

        // Act: caller attempts to call withdrawAll
        vm.prank(caller);
        c.withdrawAll(caller);

        uint256 balanceAfter = address(c).balance;

        // General rule: balance should remain unchanged when caller is not owner
        assertTrue(balanceAfter == balanceBefore);
    }
}

