import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address recipient) public {
        vm.assume(recipient != address(0));
        uint256 sizeBefore;
        address ownerBefore = c.owner();
        assembly { sizeBefore := extcodesize(c) }

        c.withdrawAll(recipient);

        uint256 sizeAfter;
        assembly { sizeAfter := extcodesize(c) }
        bool exists = sizeAfter > 0;
        bool ownerUnchanged = c.owner() == ownerBefore;

        assertTrue(exists && ownerUnchanged);
    }
}

